        if left == right.left:
            # Simplify a - (a + b) to -b
            return -right.right
        if left == right.right:
            # Simplify a - (b + a) to -b
            return -right.left
    elif isinstance(right, Subtraction):
        if left == right.left:
            # Simplify a - (a - b) to b
            return right.right

    return pybamm.simplify_if_constant(Subtraction(left, right))


